operation.add:
if (!empty($GLOBALS['better_http_force_native_socket']))
{
	$GLOBALS['better_http_native_socket_attempted'] = true;
	$GLOBALS['better_http_native_socket_connected'] = !empty($fp);
	$GLOBALS['better_http_native_socket_error'] = empty($fp) && isset($err) ? (string) $err : '';
}

if (function_exists('BetterHttp_RecordNativeSocketObservation'))
	BetterHttp_RecordNativeSocketObservation(!empty($fp), empty($fp) && isset($err) ? (string) $err : '');
